{"witnessCode": "import { describe, it } from 'node:test'
import assert from 'node:assert/strict'
import normalizeUrl from '../index.js'

describe('normalizeUrl removeDirectoryIndex bug', () => {
  it('should not remove directory index when options.removeDirectoryIndex is array-like object', () => {
    const input = 'http://example.com/index.html'
    const opts = {
      removeDirectoryIndex: {
        '0': /^index\.[a-z]+$/,
        length: 1
      }
    }
    const expected = 'http://example.com/index.html'
    assert.strictEqual(normalizeUrl(input, opts), expected)
  })
})"}
